// ── 1. Structured logging with pino ─────────────────────────────
import pino from 'pino';
import { randomUUID } from 'crypto';
import express from 'express';

const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  // In development, use pino-pretty for human-readable output.
  // In production, emit raw JSON for log aggregators.
});

const app = express();

// 2. Correlation ID middleware — generate or propagate
app.use((req, res, next) => {
  // Accept an incoming correlation ID from upstream services
  // or generate a new one at the entry point.
  const correlationId = req.headers['x-correlation-id'] ?? randomUUID();
  res.setHeader('x-correlation-id', correlationId);

  // Bind the correlation ID to every log line in this request
  req.log = logger.child({ correlationId, path: req.path, method: req.method });
  next();
});

// 3. Request logging — structured, not a string
app.use((req, res, next) => {
  const start = Date.now();
  req.log.info({ event: 'request.start' });

  res.on('finish', () => {
    const durationMs = Date.now() - start;
    const level = res.statusCode >= 500 ? 'error'
                : res.statusCode >= 400 ? 'warn' : 'info';
    req.log[level]({
      event: 'request.end',
      statusCode: res.statusCode,
      durationMs,
    });
  });
  next();
});

// 4. OpenTelemetry tracing (abridged setup)
// In a real app, configure this in a separate otel.js loaded before all imports:
