import { trace, SpanStatusCode } from '@opentelemetry/api';
const tracer = trace.getTracer('order-service', '1.0.0');

async function createOrder(userId, items) {
  // Creates a span — auto-linked to the active parent span from HTTP context
  return tracer.startActiveSpan('createOrder', async (span) => {
    try {
      span.setAttributes({ 'user.id': userId, 'order.item_count': items.length });

      const payment = await chargeCard(userId, calculateTotal(items));
      span.addEvent('payment.completed', { paymentId: payment.id });

      span.setStatus({ code: SpanStatusCode.OK });
      return { orderId: randomUUID(), paymentId: payment.id };
    } catch (err) {
      span.recordException(err);
      span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
      throw err;
    } finally {
      span.end();
    }
  });
}

console.log('Order service running with structured logs + OTel tracing');

